class Solution:
    def resultArray(self, nums: List[int], k: int) -> List[int]:
        res = [0] * k
        dp = [0] * k
        for a in nums:
            am = a % k
            ndp = [0] * k
            ndp[am] += 1
            for x in range(k):
                if dp[x]:
                    ndp[x * am % k] += dp[x]
            dp = ndp
            for x in range(k):
                res[x] += dp[x]
        return res

