class Solution {
public:
    vector<long long> resultArray(vector<int>& nums, int k) {
        int kk = k;
        vector<long long> res(kk, 0), dp(kk, 0), ndp(kk);
        for (int a : nums) {
            int am = a % kk;
            fill(ndp.begin(), ndp.end(), 0LL);
            ndp[am]++;
            for (int x = 0; x < kk; x++)
                if (dp[x]) ndp[(int)((long long)x * am % kk)] += dp[x];
            dp = ndp;
            for (int x = 0; x < kk; x++) res[x] += dp[x];
        }
        return res;
    }
};

c.java:
class Solution {
    public long[] resultArray(int[] nums, int k) {
        long[] res = new long[k], dp = new long[k], ndp = new long[k];
        for (int a : nums) {
            int am = a % k;
            java.util.Arrays.fill(ndp, 0);
            ndp[am]++;
            for (int x = 0; x < k; x++)
                if (dp[x] > 0) ndp[(int)((long) x * am % k)] += dp[x];
            System.arraycopy(ndp, 0, dp, 0, k);
            for (int x = 0; x < k; x++) res[x] += dp[x];
        }
        return res;
    }
}

