    let dp = new Array(k).fill(0);
    for (const a of nums) {
        const am = a % k;
        const ndp = new Array(k).fill(0);
        ndp[am]++;
        for (let x = 0; x < k; x++) if (dp[x]) ndp[(x * am) % k] += dp[x];
        dp = ndp;
        for (let x = 0; x < k; x++) res[x] += dp[x];
    }
    return res;
